import { createChart, removeChart } from '../test/ut/core/utHelper';
import { EChartsType } from '../src/echarts.all';
import CompoundPath from 'zrender/src/graphic/CompoundPath';
import Element from 'zrender/src/Element';

function findByType(list: Element[], type: string): Element[] {
    const found: Element[] = [];
    for (let i = 0; i < list.length; i++) {
        const el = list[i];
        if (el.type === type) {
            found.push(el);
        }
    }
    return found;
}

describe('custom-renderitem-compoundpath', function () {

    let chart: EChartsType;
    afterEach(function () {
        removeChart(chart);
        chart = null;
    });

    it('renderItem supports compoundPath and honors shape.paths', function () {
        chart = createChart();
        chart.setOption({
            xAxis: { data: ['a'] },
            yAxis: {},
            series: [{
                type: 'custom',
                renderItem: function () {
                    return {
                        type: 'compoundPath',
                        shape: {
                            paths: [
                                { type: 'rect', shape: { x: 10, y: 10, width: 20, height: 20 } },
                                { type: 'circle', shape: { cx: 30, cy: 30, r: 5 } },
                                { type: 'path', shape: { pathData: 'M0,0 L10,0 L10,10 Z' } }
                            ]
                        },
                        style: { fill: 'red' }
                    };
                },
                data: [11]
            }]
        });

        const displayList = chart.getZr().storage.getDisplayList();
        const compounds = findByType(displayList, 'compound') as CompoundPath[];
        expect(compounds.length).toBe(1);
        // shape.paths is honored: three subpaths were built as Path instances
        const paths = compounds[0].shape.paths;
        expect(paths.length).toBe(3);
        expect(paths[0].type).toBe('rect');
        expect((paths[0] as any).shape.width).toBe(20);
        expect(paths[1].type).toBe('circle');
        expect((paths[1] as any).shape.r).toBe(5);
        expect(typeof paths[2].buildPath).toBe('function');
        // style is applied on the compound element
        expect((compounds[0] as any).style.fill).toBe('red');
    });

    it('compoundPath without shape.paths fails clearly', function () {
        chart = createChart();
        expect(function () {
            chart.setOption({
                xAxis: { data: ['a'] },
                yAxis: {},
                series: [{
                    type: 'custom',
                    renderItem: function () {
                        return {
                            type: 'compoundPath'
                        };
                    },
                    data: [11]
                }]
            });
        }).toThrow('shape.paths must be specified in compoundPath');
    });
});

